def summarize_ranges(nums):
    if not nums:
        return ""

    nums = sorted(set(nums))
    ranges = []
    start = nums[0]
    prev = nums[0]

    for num in nums[1:]:
        if num == prev + 1:
            prev = num
        else:
            if start == prev:
                ranges.append(str(start))
            elif prev - start == 1:
                ranges.append(str(start))
                ranges.append(str(prev))
            else:
                ranges.append(f"{start}..{prev}")
            start = num
            prev = num

    if start == prev:
        ranges.append(str(start))
    elif prev - start == 1:
        ranges.append(str(start))
        ranges.append(str(prev))
    else:
        ranges.append(f"{start}..{prev}")

    return ",".join(ranges)
